-- Reuse confirmed sale/COGS identity; a credit sale is not a treasury receipt.
begin;
alter table public.zp_cash_receipts drop constraint zp_cash_receipts_method_check;
alter table public.zp_cash_receipts add constraint zp_cash_receipts_method_check check(method in ('cash','mtn_momo','orange_money','bank','card','mixed','credit'));
create table public.zp_credit_accounts(
 id uuid primary key default gen_random_uuid(),org_id uuid not null,site_id uuid not null,customer_id uuid not null,
 limit_xaf bigint not null check(limit_xaf between 1 and 2147483647),created_by uuid not null,created_at timestamptz not null default now(),
 unique(site_id,customer_id),unique(id,org_id,site_id),foreign key(site_id,org_id) references public.zp_site_modes(site_id,org_id),
 foreign key(customer_id,org_id) references public.zp_customers(id,org_id),foreign key(created_by,org_id) references public.zp_members(id,org_id));
create table public.zp_credit_sales(
 id uuid primary key default gen_random_uuid(),org_id uuid not null,site_id uuid not null,account_id uuid not null,order_id uuid not null unique,
 receipt_id uuid not null unique,member_id uuid not null,request_id uuid not null,due_on date not null,reason text not null check(length(reason) between 5 and 500),
 amount_xaf bigint not null check(amount_xaf>0),paid_xaf bigint not null default 0 check(paid_xaf>=0 and paid_xaf<=amount_xaf),refunded_xaf bigint not null default 0 check(refunded_xaf>=0 and refunded_xaf<=paid_xaf),credit_note_xaf bigint not null default 0 check(credit_note_xaf>=0 and credit_note_xaf<=amount_xaf),balance_xaf bigint generated always as (amount_xaf-paid_xaf+refunded_xaf-credit_note_xaf) stored check(balance_xaf>=0),
 created_at timestamptz not null default now(),unique(member_id,request_id),unique(id,org_id,site_id),
 foreign key(account_id,org_id,site_id) references public.zp_credit_accounts(id,org_id,site_id),foreign key(order_id,org_id,site_id) references public.zp_orders(id,org_id,site_id),
 foreign key(receipt_id,org_id,site_id) references public.zp_cash_receipts(id,org_id,site_id),foreign key(member_id,org_id) references public.zp_members(id,org_id));
create table public.zp_credit_payments(
 id uuid primary key default gen_random_uuid(),org_id uuid not null,site_id uuid not null,sale_id uuid not null,cash_id uuid not null,member_id uuid not null,request_id uuid not null,
 amount_xaf bigint not null check(amount_xaf between 1 and 2147483647),method text not null check(method in ('cash','mtn_momo','orange_money','bank','card')),
 reference text,created_at timestamptz not null default now(),unique(member_id,request_id),
 foreign key(sale_id,org_id,site_id) references public.zp_credit_sales(id,org_id,site_id),foreign key(cash_id,org_id,site_id) references public.zp_cash_sessions(id,org_id,site_id),
 foreign key(member_id,org_id) references public.zp_members(id,org_id),
 check((method='cash' and reference is null) or (method<>'cash' and reference is not null and length(reference) between 4 and 160)));

-- Shared bills reuse the existing receivable/collection and sale-cost machinery.
-- A null account is a temporary bill, not an authorized customer credit account.
alter table public.zp_credit_sales alter column account_id drop not null,add column split_mode text,
 add constraint zp_credit_sale_kind check ((account_id is not null and split_mode is null) or (account_id is null and split_mode in ('amount','items') and split_mode is not null));
create table public.zp_split_parts(
 payment_id uuid primary key references public.zp_credit_payments(id),org_id uuid not null,site_id uuid not null,
 sale_id uuid not null,payer text not null check(length(payer) between 1 and 80),
 allocations jsonb not null check(jsonb_typeof(allocations)='array'),
 foreign key(sale_id,org_id,site_id) references public.zp_credit_sales(id,org_id,site_id));
alter table public.zp_split_parts enable row level security;
revoke all on public.zp_split_parts from public,anon,authenticated;
grant select,insert on public.zp_split_parts to service_role;
create function public.zp_split_lines(p_order uuid) returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $split$
 select coalesce(jsonb_agg(jsonb_build_object('line_no',x.n,'name',x.line->>'name','qty',(x.line->>'qty')::int,'price_xaf',(x.line->>'price_xaf')::bigint,'choices',x.line->'choices','remaining_qty',(x.line->>'qty')::int-coalesce((select sum(a.qty) from public.zp_split_parts p join public.zp_credit_sales s on s.id=p.sale_id cross join lateral jsonb_to_recordset(p.allocations) as a(line_no int,qty int) where s.order_id=o.id and a.line_no=x.n),0)) order by x.n),'[]'::jsonb)
 from public.zp_orders o cross join lateral jsonb_array_elements(o.commercial_lines) with ordinality as x(line,n) where o.id=p_order;
$split$;
create function public.zp_split_snapshot(p_access text,p_site uuid) returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $split$
declare m public.zp_members;begin m:=public.zp_business_actor(p_access,p_site);
 if not public.zp_can_operate(m.id,p_site,'cash') then raise exception 'DENIED';end if;
 return jsonb_build_object('cash_sessions',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'label',coalesce(d.label,'Caisse principale')) order by d.label nulls first) from public.zp_cash_sessions c left join public.zp_cash_desks d on d.id=c.desk_id where c.org_id=m.org_id and c.site_id=p_site and c.closed_at is null and public.zp_cash_desk_access(m.id,c.id)),'[]'::jsonb),
 'orders',coalesce((select jsonb_agg(to_jsonb(v) order by v.number) from (select o.id,o.service_number number,o.total_xaf,coalesce(s.balance_xaf,o.total_xaf) balance_xaf,s.split_mode,public.zp_split_lines(o.id) lines,coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'payer',k.payer,'amount_xaf',p.amount_xaf,'method',p.method,'reference',p.reference,'allocations',k.allocations,'created_at',p.created_at) order by p.created_at,p.id) from public.zp_split_parts k join public.zp_credit_payments p on p.id=k.payment_id where k.sale_id=s.id),'[]'::jsonb) parts from public.zp_orders o left join public.zp_cash_receipts cr on cr.order_id=o.id left join public.zp_credit_sales s on s.receipt_id=cr.id where o.org_id=m.org_id and o.site_id=p_site and o.status='served' and (cr.id is null or s.split_mode is not null) order by o.created_at desc limit 200)v),'[]'::jsonb));end $split$;
create function public.zp_split_collect(p_access text,p_site uuid,p_cash uuid,p_order uuid,p_request uuid,p_payer text,p_amount bigint,p_method text,p_reference text,p_allocations jsonb) returns jsonb language plpgsql security invoker set search_path=pg_catalog,public as $split$
declare m public.zp_members;c public.zp_cash_sessions;o public.zp_orders;s public.zp_credit_sales;x public.zp_credit_payments;k public.zp_split_parts;receipt uuid;sid uuid;pid uuid;mode_code text;alloc jsonb;row_value record;line_value jsonb;expected bigint:=0;ref text;who text:=trim(coalesce(p_payer,''));begin
 m:=public.zp_business_actor(p_access,p_site);if not public.zp_can_operate(m.id,p_site,'cash') then raise exception 'DENIED';end if;
 if p_request is null or length(who) not between 1 and 80 or p_amount is null or p_amount not between 1 and 2147483647 or p_method is null or p_method not in ('cash','mtn_momo','orange_money','bank','card') then raise exception 'INVALID_SPLIT';end if;
 ref:=case when p_method='cash' then null else trim(p_reference) end;
 if p_method<>'cash' and (ref is null or length(ref) not between 4 and 160) then raise exception 'INVALID_SPLIT';end if;
 if jsonb_typeof(p_allocations) is distinct from 'array' or jsonb_array_length(p_allocations)>100 then raise exception 'INVALID_SPLIT';end if;
 if exists(select 1 from jsonb_array_elements(p_allocations) a where jsonb_typeof(a)<>'object' or coalesce(a->>'line_no','') !~ '^[1-9][0-9]{0,3}$' or coalesce(a->>'qty','') !~ '^[1-9][0-9]{0,3}$') then raise exception 'INVALID_SPLIT';end if;
 select coalesce(jsonb_agg(jsonb_build_object('line_no',a.line_no,'qty',a.qty) order by a.line_no),'[]'::jsonb) into alloc from jsonb_to_recordset(p_allocations) as a(line_no int,qty int);
 if (select count(distinct a.line_no) from jsonb_to_recordset(alloc) as a(line_no int,qty int))<>jsonb_array_length(alloc) then raise exception 'INVALID_SPLIT';end if;
 mode_code:=case when jsonb_array_length(alloc)=0 then 'amount' else 'items' end;
 perform 1 from public.zp_site_modes where site_id=p_site and org_id=m.org_id for update;
 select * into c from public.zp_cash_sessions where id=p_cash and org_id=m.org_id and site_id=p_site for update;
 if c.id is null or not public.zp_cash_desk_access(m.id,c.id) then raise exception 'DENIED';end if;
 select * into x from public.zp_credit_payments where member_id=m.id and request_id=p_request;
 if x.id is not null then
  select * into k from public.zp_split_parts where payment_id=x.id;
  select * into s from public.zp_credit_sales where id=x.sale_id;
  if k.payment_id is null or (x.site_id,x.cash_id,s.order_id,x.amount_xaf,x.method,x.reference,k.payer,k.allocations) is distinct from (p_site,p_cash,p_order,p_amount,p_method,ref,who,alloc) then raise exception 'IDEMPOTENCY_CONFLICT';end if;
  return jsonb_build_object('payment_id',x.id,'receipt_id',s.receipt_id,'balance_xaf',s.balance_xaf,'paid_xaf',s.paid_xaf);
 end if;
 if c.closed_at is not null then raise exception 'CASH_CLOSED';end if;
 select * into o from public.zp_orders where id=p_order and org_id=m.org_id and site_id=p_site for update;
 if o.id is null or o.status<>'served' or o.total_xaf<=0 then raise exception 'SALE_NOT_SETTLEABLE';end if;
 if o.table_session_id is not null and not exists(select 1 from public.zp_table_sessions where id=coalesce(o.billing_session_id,o.table_session_id) and org_id=m.org_id and site_id=p_site and closed_at is null) then raise exception 'TABLE_CLOSED';end if;
 select * into s from public.zp_credit_sales where order_id=o.id for update;
 if s.id is not null and (s.split_mode is distinct from mode_code or s.account_id is not null) then raise exception 'INVALID_SPLIT';end if;
 if s.id is null and exists(select 1 from public.zp_cash_receipts where order_id=o.id) then raise exception 'SALE_NOT_SETTLEABLE';end if;
 if p_amount>coalesce(s.balance_xaf,o.total_xaf) then raise exception 'SPLIT_EXCEEDS_BALANCE';end if;
 if mode_code='items' then
  for row_value in select * from jsonb_to_recordset(alloc) as a(line_no int,qty int) loop
   select v into line_value from jsonb_array_elements(public.zp_split_lines(o.id)) v where (v->>'line_no')::int=row_value.line_no;
   if line_value is null or row_value.qty>(line_value->>'remaining_qty')::int then raise exception 'SPLIT_EXCEEDS_QUANTITY';end if;
   expected:=expected+row_value.qty*(line_value->>'price_xaf')::bigint;
  end loop;
  if expected<>p_amount then raise exception 'INVALID_SPLIT';end if;
 end if;
 if s.id is null then
  insert into public.zp_cash_receipts(org_id,site_id,cash_id,order_id,member_id,request_id,method,amount_xaf,reference) values(m.org_id,p_site,c.id,o.id,m.id,gen_random_uuid(),'credit',o.total_xaf,null) returning id into receipt;
  insert into public.zp_credit_sales(org_id,site_id,account_id,order_id,receipt_id,member_id,request_id,due_on,reason,amount_xaf,split_mode) values(m.org_id,p_site,null,o.id,receipt,m.id,gen_random_uuid(),(now() at time zone 'Africa/Douala')::date,'Addition fractionnée',o.total_xaf,mode_code) returning id into sid;
 else sid:=s.id;end if;
 if p_method<>'cash' then insert into public.zp_settlement_references values(m.org_id,p_method,ref) on conflict do nothing;if not found then raise exception 'SPLIT_REFERENCE_USED';end if;end if;
 insert into public.zp_credit_payments(org_id,site_id,sale_id,cash_id,member_id,request_id,amount_xaf,method,reference) values(m.org_id,p_site,sid,c.id,m.id,p_request,p_amount,p_method,ref) returning id into pid;
 insert into public.zp_split_parts(payment_id,org_id,site_id,sale_id,payer,allocations) values(pid,m.org_id,p_site,sid,who,alloc);
 update public.zp_credit_sales set paid_xaf=paid_xaf+p_amount where id=sid returning * into s;
 return jsonb_build_object('payment_id',pid,'receipt_id',s.receipt_id,'balance_xaf',s.balance_xaf,'paid_xaf',s.paid_xaf);end $split$;
revoke all on function public.zp_split_lines(uuid),public.zp_split_snapshot(text,uuid),public.zp_split_collect(text,uuid,uuid,uuid,uuid,text,bigint,text,text,jsonb) from public,anon,authenticated;
grant execute on function public.zp_split_lines(uuid),public.zp_split_snapshot(text,uuid),public.zp_split_collect(text,uuid,uuid,uuid,uuid,text,bigint,text,text,jsonb) to service_role;

create function public.zp_credit_status(p_order uuid) returns text language sql stable security invoker set search_path=pg_catalog,public as $$
 select coalesce((select case when r.method='credit' and (s.id is null or s.balance_xaf>0) then case when s.split_mode is not null then 'partial_due' else 'credit_due' end else 'paid' end from public.zp_cash_receipts r left join public.zp_credit_sales s on s.receipt_id=r.id where r.order_id=p_order),'unpaid');
$$;
create function public.zp_credit_account_add(p_access text,p_site uuid,p_customer uuid,p_limit bigint) returns uuid language plpgsql security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;i uuid;begin m:=public.zp_erp_actor(p_access,p_site);
 if m.role_code<>'promoteur' or not exists(select 1 from public.zp_customers where id=p_customer and org_id=m.org_id) then raise exception 'DENIED';end if;
 if p_limit is null or p_limit not between 1 and 2147483647 then raise exception 'INVALID_CREDIT_LIMIT';end if;
 insert into public.zp_credit_accounts(org_id,site_id,customer_id,limit_xaf,created_by) values(m.org_id,p_site,p_customer,p_limit,m.id) returning id into i;return i;end $$;
create function public.zp_credit_authorize(p_access text,p_site uuid,p_account uuid,p_cash uuid,p_order uuid,p_request uuid,p_due date,p_reason text) returns uuid language plpgsql security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;a public.zp_credit_accounts;c public.zp_cash_sessions;o public.zp_orders;x public.zp_credit_sales;debt bigint;rid uuid;i uuid;why text:=trim(coalesce(p_reason,''));begin
 m:=public.zp_erp_actor(p_access,p_site);if m.role_code<>'promoteur' then raise exception 'DENIED';end if;
 perform 1 from public.zp_site_modes where site_id=p_site for update;
 select * into x from public.zp_credit_sales where member_id=m.id and request_id=p_request;
 if x.id is not null then
  if (x.site_id,x.account_id,x.order_id,x.due_on,x.reason) is distinct from (p_site,p_account,p_order,p_due,why) or not exists(select 1 from public.zp_cash_receipts where id=x.receipt_id and cash_id=p_cash) then raise exception 'IDEMPOTENCY_CONFLICT';end if;return x.id;
 end if;
 select * into a from public.zp_credit_accounts where id=p_account and org_id=m.org_id and site_id=p_site for update;if a.id is null then raise exception 'DENIED';end if;
 select * into c from public.zp_cash_sessions where id=p_cash and org_id=m.org_id and site_id=p_site for update;if c.id is null or not public.zp_cash_desk_access(m.id,c.id) then raise exception 'DENIED';end if;if c.closed_at is not null then raise exception 'CASH_CLOSED';end if;
 if p_request is null or p_due is null or p_due<(now() at time zone 'Africa/Douala')::date or length(why) not between 5 and 500 then raise exception 'INVALID_CREDIT_SALE';end if;
 select * into o from public.zp_orders where id=p_order and org_id=m.org_id and site_id=p_site for update;
 if o.id is null or o.status<>'served' or o.total_xaf<=0 or exists(select 1 from public.zp_cash_receipts where order_id=p_order) then raise exception 'SALE_NOT_SETTLEABLE';end if;
 select coalesce(sum(balance_xaf),0) into debt from public.zp_credit_sales where account_id=a.id;
 if debt+o.total_xaf>a.limit_xaf then raise exception 'CREDIT_LIMIT_EXCEEDED';end if;
 perform public.zp_customer_attach(p_access,p_site,a.customer_id,o.id);
 insert into public.zp_cash_receipts(org_id,site_id,cash_id,order_id,member_id,request_id,method,amount_xaf,reference) values(m.org_id,p_site,c.id,o.id,m.id,gen_random_uuid(),'credit',o.total_xaf,null) returning id into rid;
 insert into public.zp_credit_sales(org_id,site_id,account_id,order_id,receipt_id,member_id,request_id,due_on,reason,amount_xaf) values(m.org_id,p_site,a.id,o.id,rid,m.id,p_request,p_due,why,o.total_xaf) returning id into i;return i;end $$;
create function public.zp_credit_collect(p_access text,p_site uuid,p_sale uuid,p_cash uuid,p_request uuid,p_amount bigint,p_method text,p_reference text) returns uuid language plpgsql security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;s public.zp_credit_sales;c public.zp_cash_sessions;x public.zp_credit_payments;i uuid;ref text;begin
 m:=public.zp_business_actor(p_access,p_site);if not public.zp_can_operate(m.id,p_site,'cash') then raise exception 'DENIED';end if;
 ref:=case when p_method='cash' then null else trim(p_reference) end;
 perform 1 from public.zp_site_modes where site_id=p_site for update;
 select * into c from public.zp_cash_sessions where id=p_cash and org_id=m.org_id and site_id=p_site for update;if c.id is null or not public.zp_cash_desk_access(m.id,c.id) then raise exception 'DENIED';end if;
 select * into x from public.zp_credit_payments where member_id=m.id and request_id=p_request;
 if x.id is not null then if (x.site_id,x.sale_id,x.cash_id,x.amount_xaf,x.method,x.reference) is distinct from (p_site,p_sale,p_cash,p_amount,p_method,ref) then raise exception 'IDEMPOTENCY_CONFLICT';end if;return x.id;end if;
 if c.closed_at is not null then raise exception 'CASH_CLOSED';end if;
 select * into s from public.zp_credit_sales where id=p_sale and org_id=m.org_id and site_id=p_site for update;if s.id is null or s.split_mode is not null then raise exception 'DENIED';end if;
 if p_request is null or p_amount is null or p_amount not between 1 and s.balance_xaf or p_method is null or p_method not in ('cash','mtn_momo','orange_money','bank','card') or (p_method<>'cash' and (ref is null or length(ref) not between 4 and 160)) then raise exception 'CREDIT_PAYMENT_EXCEEDS_BALANCE';end if;
 if p_method<>'cash' then insert into public.zp_settlement_references values(m.org_id,p_method,ref);end if;
 insert into public.zp_credit_payments(org_id,site_id,sale_id,cash_id,member_id,request_id,amount_xaf,method,reference) values(m.org_id,p_site,s.id,c.id,m.id,p_request,p_amount,p_method,ref) returning id into i;
 update public.zp_credit_sales set paid_xaf=paid_xaf+p_amount where id=s.id;return i;end $$;
create function public.zp_credit_snapshot(p_access text,p_site uuid) returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;begin m:=public.zp_erp_actor(p_access,p_site);
 return jsonb_build_object('customers',coalesce((select jsonb_agg(jsonb_build_object('id',id,'name',display_name) order by display_name) from public.zp_customers where org_id=m.org_id),'[]'::jsonb),
 'accounts',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'customer_id',a.customer_id,'name',c.display_name,'limit_xaf',a.limit_xaf,'balance_xaf',(select coalesce(sum(balance_xaf),0) from public.zp_credit_sales where account_id=a.id)) order by c.display_name) from public.zp_credit_accounts a join public.zp_customers c on c.id=a.customer_id where a.org_id=m.org_id and a.site_id=p_site),'[]'::jsonb),
 'sales',coalesce((select jsonb_agg(to_jsonb(s) order by s.due_on) from (select id,account_id,order_id,due_on,reason,amount_xaf,paid_xaf,refunded_xaf,credit_note_xaf,balance_xaf,created_at from public.zp_credit_sales where org_id=m.org_id and site_id=p_site and account_id is not null)s),'[]'::jsonb),
 'payments',coalesce((select jsonb_agg(to_jsonb(p) order by p.created_at desc) from (select id,sale_id,amount_xaf,method,reference,created_at from public.zp_credit_payments where org_id=m.org_id and site_id=p_site and sale_id in (select id from public.zp_credit_sales where account_id is not null))p),'[]'::jsonb));end $$;
create or replace function public.zp_business_snapshot(p_access text,p_site uuid) returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;mode jsonb;items jsonb;orders jsonb;tables jsonb;begin m:=public.zp_business_actor(p_access,p_site);if not public.zp_can_operate(m.id,p_site,'order') then raise exception 'DENIED';end if;
 select to_jsonb(s) into mode from public.zp_site_modes s where s.site_id=p_site and s.org_id=m.org_id;
 select coalesce(jsonb_agg(to_jsonb(i)||jsonb_build_object('sellable_qty',public.zp_sellable_qty(i.id),'channels',jsonb_build_object('table',jsonb_build_object('price_xaf',public.zp_current_price(i.id,'table'),'qty',public.zp_sellable_channel_qty(i.id,'table'),'groups',public.zp_formula_groups_view(i.id,'table')),'counter',jsonb_build_object('price_xaf',public.zp_current_price(i.id,'counter'),'qty',public.zp_sellable_channel_qty(i.id,'counter'),'groups',public.zp_formula_groups_view(i.id,'counter')),'takeaway',jsonb_build_object('price_xaf',public.zp_current_price(i.id,'takeaway'),'qty',public.zp_sellable_channel_qty(i.id,'takeaway'),'groups',public.zp_formula_groups_view(i.id,'takeaway')))) order by i.name),'[]'::jsonb) into items from public.zp_menu_items i where i.site_id=p_site and i.org_id=m.org_id;
 select coalesce(jsonb_agg(x.data),'[]'::jsonb) into orders from (select jsonb_build_object('id',o.id,'number',o.service_number,'table_session_id',o.table_session_id,'initial_promised_at',o.initial_promised_at,'guest_served_at',o.guest_served_at,'priority',o.priority,'called_at',o.called_at,'no_show_at',o.no_show_at,'eta_saturated',o.eta_saturated,'channel',o.channel,'status',o.status,'total_xaf',o.total_xaf,'paid',public.zp_credit_status(o.id)='paid','settled',public.zp_credit_status(o.id)<>'unpaid','payment_status',public.zp_credit_status(o.id),'balance_xaf',case when public.zp_credit_status(o.id)='partial_due' then (select balance_xaf from public.zp_credit_sales where order_id=o.id) when public.zp_credit_status(o.id)='unpaid' then o.total_xaf else 0 end,'promised_at',o.promised_at,'served_at',o.served_at,'created_at',o.created_at,'commercial_lines',o.commercial_lines,'lines',(select jsonb_agg(jsonb_build_object('item_id',l.item_id,'name',i.name,'qty',l.qty,'post',l.post,'substation_id',l.substation_id,'substation_label',(select label from public.zp_substations where id=l.substation_id),'state',l.state,'line_total_xaf',l.line_total_xaf,'instructions',l.instructions)) from public.zp_order_lines l join public.zp_menu_items i on i.id=l.item_id where l.order_id=o.id)) data from public.zp_orders o where o.site_id=p_site and o.org_id=m.org_id order by case when o.status in ('received','preparing','ready') then 0 else 1 end,o.priority desc,case when o.status in ('received','preparing','ready') then o.created_at end, o.created_at desc limit 100) x;
 select coalesce(jsonb_agg(jsonb_build_object('id',t.id,'label',t.label,'kind',t.kind,'session_id',(select id from public.zp_table_sessions s where s.table_id=t.id and s.closed_at is null))),'[]'::jsonb) into tables from public.zp_tables t where t.site_id=p_site and t.org_id=m.org_id;
 return jsonb_build_object('mode',mode,'operation_roles',coalesce((select jsonb_agg(role) from public.zp_operational_grants where site_id=p_site and member_id=m.id),'[]'::jsonb),'items',items,'orders',orders,'tables',tables,'cash_session',case when public.zp_can_operate(m.id,p_site,'cash') then (select jsonb_build_object('id',c.id,'opening_xaf',c.opening_xaf,'opened_at',c.opened_at) from public.zp_cash_sessions c where c.org_id=m.org_id and c.site_id=p_site and c.closed_at is null and c.desk_id is null) else null end,'plan',public.zp_paid_plan(m.org_id),'server_now',now());end $$;
create or replace function public.zp_guest_order(p_guest_hash text,p_order uuid) returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 select jsonb_build_object('id',o.id,'number',o.service_number,'channel',o.channel,'called_at',o.called_at,'eta_saturated',o.eta_saturated,'initial_promised_at',o.initial_promised_at,'commercial_lines',o.commercial_lines,'paid',public.zp_credit_status(o.id)='paid','settled',public.zp_credit_status(o.id)<>'unpaid','payment_status',public.zp_credit_status(o.id),'balance_xaf',case when public.zp_credit_status(o.id)='partial_due' then (select balance_xaf from public.zp_credit_sales where order_id=o.id) when public.zp_credit_status(o.id)='unpaid' then o.total_xaf else 0 end,'cash_feedback_eligible',(exists(select 1 from public.zp_cash_receipts cr where cr.order_id=o.id and cr.org_id=o.org_id and cr.site_id=o.site_id and cr.method<>'credit') or exists(select 1 from public.zp_credit_payments cp join public.zp_credit_sales cs on cs.id=cp.sale_id and cs.org_id=cp.org_id and cs.site_id=cp.site_id where cs.order_id=o.id and cs.org_id=o.org_id and cs.site_id=o.site_id)),'cash_feedback_rating',(select fp.rating from public.zp_feedback_posts fp where fp.order_id=o.id and fp.post='cash'),'lines',(select jsonb_agg(jsonb_build_object('item_id',l.item_id,'name',i.name,'qty',l.qty,'unit_xaf',l.unit_xaf,'line_total_xaf',l.line_total_xaf,'state',l.state,'post',l.post,'substation_id',l.substation_id,'substation_label',(select label from public.zp_substations where id=l.substation_id))) from public.zp_order_lines l join public.zp_menu_items i on i.id=l.item_id where l.order_id=o.id),'status',o.status,'total_xaf',o.total_xaf,'created_at',o.created_at,'promised_at',o.promised_at,'served_at',o.served_at,'guest_served_at',o.guest_served_at,'server_now',now(),'service_delta_seconds',case when o.guest_served_at is not null and o.promised_at is not null then extract(epoch from o.guest_served_at-o.promised_at)::bigint else null end) from public.zp_orders o join public.zp_guest_sessions g on g.id=o.guest_id join public.zp_table_sessions ts on ts.id=g.table_session_id join public.zp_sites si on si.id=o.site_id join public.zp_organizations org on org.id=o.org_id where o.id=p_order and g.token_hash=p_guest_hash and g.expires_at>now() and ts.closed_at is null and si.active and org.active and public.zp_operational_plan(o.org_id) is not null
$$;
create or replace function public.zp_table_bill(p_access text,p_site uuid,p_session uuid) returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;begin m:=public.zp_business_actor(p_access,p_site);if not public.zp_can_operate(m.id,p_site,'bill') then raise exception 'DENIED';end if;
 if not exists(select 1 from public.zp_table_sessions where id=p_session and org_id=m.org_id and site_id=p_site) then raise exception 'DENIED';end if;
 return jsonb_build_object('total_xaf',(select coalesce(sum(total_xaf),0) from public.zp_orders where coalesce(billing_session_id,table_session_id)=p_session and status<>'cancelled'),'unpaid_xaf',(select coalesce(sum(case when public.zp_credit_status(o.id)='partial_due' then (select balance_xaf from public.zp_credit_sales where order_id=o.id) when public.zp_credit_status(o.id)='unpaid' then o.total_xaf else 0 end),0) from public.zp_orders o where coalesce(o.billing_session_id,o.table_session_id)=p_session and o.status<>'cancelled'),'orders',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'number',o.service_number,'total_xaf',o.total_xaf,'status',o.status,'paid',public.zp_credit_status(o.id)='paid','settled',public.zp_credit_status(o.id)<>'unpaid','payment_status',public.zp_credit_status(o.id),'balance_xaf',case when public.zp_credit_status(o.id)='partial_due' then (select balance_xaf from public.zp_credit_sales where order_id=o.id) when public.zp_credit_status(o.id)='unpaid' then o.total_xaf else 0 end) order by o.service_number) from public.zp_orders o where coalesce(o.billing_session_id,o.table_session_id)=p_session and o.status<>'cancelled'),'[]'::jsonb));end $$;
create or replace function public.zp_crm_snapshot(p_access text,p_site uuid) returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;begin m:=public.zp_erp_actor(p_access,p_site);
 return jsonb_build_object('customers',coalesce((select jsonb_agg(to_jsonb(c) order by c.display_name) from (select id,display_name,phone from public.zp_customers where org_id=m.org_id order by display_name limit 200)c),'[]'::jsonb),'followups',coalesce((select jsonb_agg(to_jsonb(f) order by f.due_on) from (select id,customer_id,title,channel,due_on,completed_at from public.zp_customer_followups where org_id=m.org_id and site_id=p_site order by completed_at nulls first,due_on limit 200)f),'[]'::jsonb),'history',coalesce((select jsonb_agg(to_jsonb(h)) from (select l.customer_id,l.order_id,o.total_xaf,o.status,o.created_at,(public.zp_credit_status(o.id)='paid') paid,public.zp_credit_status(o.id) payment_status from public.zp_customer_order_links l join public.zp_orders o on o.id=l.order_id left join public.zp_cash_receipts r on r.order_id=o.id where l.org_id=m.org_id and l.site_id=p_site order by o.created_at desc limit 200)h),'[]'::jsonb),'rewards_status','policy_required');end $$;
create or replace function public.zp_close_cash(p_access text,p_site uuid,p_cash uuid,p_counted bigint) returns jsonb language plpgsql security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;c public.zp_cash_sessions;expected bigint;begin m:=public.zp_business_actor(p_access,p_site);if not public.zp_can_operate(m.id,p_site,'cash') or p_counted<0 or p_counted is null then raise exception 'DENIED';end if;
 select * into c from public.zp_cash_sessions where id=p_cash and site_id=p_site and org_id=m.org_id for update;if c.id is null or not public.zp_cash_desk_access(m.id,c.id) then raise exception 'DENIED';end if;
 if c.closed_at is not null then if c.counted_xaf<>p_counted then raise exception 'CASH_CLOSED';end if;expected:=c.expected_xaf;
 else select c.opening_xaf+coalesce((select sum(amount_xaf) from public.zp_cash_receipts where cash_id=p_cash and method='cash'),0)+coalesce((select sum(t.amount_xaf) from public.zp_cash_tenders t join public.zp_cash_receipts r on r.id=t.receipt_id where r.cash_id=p_cash and t.method='cash'),0)+coalesce((select sum(p.amount_xaf) from public.zp_credit_payments p where p.cash_id=p_cash and p.method='cash'),0) into expected;
 update public.zp_cash_sessions set closed_at=clock_timestamp(),closed_by=m.id,counted_xaf=p_counted,expected_xaf=expected where id=p_cash;end if;
 return jsonb_build_object('expected_xaf',expected,'counted_xaf',p_counted,'variance_xaf',p_counted-expected);end $$;
create or replace function public.zp_erp_snapshot(p_access text,p_site uuid) returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;ingredients jsonb;lots jsonb;batches jsonb;expenses jsonb;recipes jsonb;begin m:=public.zp_erp_actor(p_access,p_site);
 select coalesce(jsonb_agg(jsonb_build_object('id',i.id,'name',i.name,'sku',i.sku,'unit',i.unit,'reorder_milli',i.reorder_milli,'supplier_whatsapp',i.supplier_whatsapp,'available_milli',coalesce((select sum(l.remaining_milli) from public.zp_ingredient_lots l where l.ingredient_id=i.id and (l.expires_on is null or l.expires_on>=(now() at time zone 'Africa/Douala')::date)),0)) order by i.name),'[]'::jsonb) into ingredients from public.zp_ingredients i where i.org_id=m.org_id and i.site_id=p_site;
 select coalesce(jsonb_agg(to_jsonb(l) order by l.received_at desc),'[]'::jsonb) into lots from (select id,ingredient_id,lot_label,supplier,remaining_milli,remaining_cost,expires_on,received_at from public.zp_ingredient_lots where org_id=m.org_id and site_id=p_site order by received_at desc limit 200) l;
 select coalesce(jsonb_agg(to_jsonb(b) order by b.created_at desc),'[]'::jsonb) into batches from (select id,item_id,servings,cost_xaf,recipe_version_id,created_at from public.zp_production_batches where org_id=m.org_id and site_id=p_site order by created_at desc limit 100) b;
 select coalesce(jsonb_agg(to_jsonb(e) order by e.created_at desc),'[]'::jsonb) into expenses from (select id,category,label,amount_xaf,method,reference,expense_date,created_at from public.zp_expenses where org_id=m.org_id and site_id=p_site order by created_at desc limit 100) e;
 select coalesce(jsonb_agg(to_jsonb(c)),'[]'::jsonb) into recipes from (select item_id,ingredient_id,qty_milli from public.zp_recipe_components where org_id=m.org_id and site_id=p_site) c;
 return jsonb_build_object('ingredients',ingredients,'lots',lots,'batches',batches,'expenses',expenses,'recipes',recipes,'conversions',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'ingredient_id',c.ingredient_id,'label',c.label,'base_milli_per_unit',c.base_milli_per_unit) order by c.label) from public.zp_unit_conversions c where c.org_id=m.org_id and c.site_id=p_site),'[]'::jsonb),'recipe_versions',coalesce((select jsonb_agg(jsonb_build_object('id',v.id,'item_id',v.item_id,'version',v.version,'components',v.components,'reason',v.reason,'created_at',v.created_at) order by v.version desc) from public.zp_recipe_versions v where v.org_id=m.org_id and v.site_id=p_site),'[]'::jsonb),'recorded_expenses_xaf',(select coalesce(sum(amount_xaf),0) from public.zp_expenses where org_id=m.org_id and site_id=p_site),'recorded_receipts_xaf',(select coalesce(sum(amount_xaf),0) from public.zp_cash_receipts where org_id=m.org_id and site_id=p_site and method<>'credit')+(select coalesce(sum(amount_xaf),0) from public.zp_credit_payments where org_id=m.org_id and site_id=p_site),'recorded_sales_xaf',(select coalesce(sum(amount_xaf),0) from public.zp_cash_receipts where org_id=m.org_id and site_id=p_site),'recorded_cost_xaf',case when exists(select 1 from public.zp_cash_receipts r where r.org_id=m.org_id and r.site_id=p_site)
 and not exists(select 1 from public.zp_cash_receipts r join public.zp_order_lines l on l.order_id=r.order_id left join public.zp_sale_costs c on c.receipt_id=r.id and c.item_id=l.item_id where r.org_id=m.org_id and r.site_id=p_site and c.cost_xaf is null)
 then (select sum(cost_xaf) from public.zp_sale_costs where org_id=m.org_id and site_id=p_site) else null end,'accounting_status','mapping_required');end $$;
create or replace function public.zp_pilotage(p_access text,p_site uuid,p_start date,p_end date) returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;today date:=(now() at time zone 'Africa/Douala')::date;lo timestamptz;hi timestamptz;revenue bigint;cost bigint;unknown_count bigint;receipt_count bigint;history jsonb;first_day date;expense bigint;low_count bigint;late_count bigint;feedback_count bigint;feedback_avg numeric;variance bigint;post_metrics jsonb;begin
 m:=public.zp_erp_actor(p_access,p_site);
 if p_start is null or p_end is null or p_start>p_end or p_end>today or p_end-p_start>365 then raise exception 'INVALID_PERIOD';end if;
 lo:=p_start::timestamp at time zone 'Africa/Douala';hi:=(p_end+1)::timestamp at time zone 'Africa/Douala';
 select coalesce(sum(r.amount_xaf),0),count(*) into revenue,receipt_count from public.zp_cash_receipts r where r.org_id=m.org_id and r.site_id=p_site and r.created_at>=lo and r.created_at<hi;
 select count(*) into unknown_count from public.zp_cash_receipts r where r.org_id=m.org_id and r.site_id=p_site and r.created_at>=lo and r.created_at<hi and exists(select 1 from public.zp_order_lines l left join public.zp_sale_costs c on c.receipt_id=r.id and c.item_id=l.item_id where l.order_id=r.order_id and c.cost_xaf is null);
 if receipt_count>0 and unknown_count=0 then select coalesce(sum(c.cost_xaf),0) into cost from public.zp_sale_costs c join public.zp_cash_receipts r on r.id=c.receipt_id where r.org_id=m.org_id and r.site_id=p_site and r.created_at>=lo and r.created_at<hi;end if;
 select coalesce(sum(amount_xaf),0) into expense from public.zp_expenses where org_id=m.org_id and site_id=p_site and expense_date between p_start and p_end;
 select count(*) into low_count from public.zp_ingredients i where i.org_id=m.org_id and i.site_id=p_site and i.reorder_milli>=coalesce((select sum(l.remaining_milli) from public.zp_ingredient_lots l where l.ingredient_id=i.id and (l.expires_on is null or l.expires_on>=today)),0);
 select count(*) into late_count from public.zp_orders o where o.org_id=m.org_id and o.site_id=p_site and o.status not in ('served','cancelled') and o.guest_served_at is null and o.promised_at<now();
 select count(*),round(avg(rating),2) into feedback_count,feedback_avg from public.zp_feedback where org_id=m.org_id and site_id=p_site and created_at>=lo and created_at<hi;
 select coalesce(sum(abs(counted_xaf-expected_xaf)),0) into variance from public.zp_cash_sessions where org_id=m.org_id and site_id=p_site and closed_at>=lo and closed_at<hi;
 select min((created_at at time zone 'Africa/Douala')::date) into first_day from public.zp_cash_receipts where org_id=m.org_id and site_id=p_site;
 select coalesce(jsonb_agg(jsonb_build_object('day',x.receipt_day,'recorded_xaf',x.amount) order by x.receipt_day),'[]'::jsonb) into history from (select (created_at at time zone 'Africa/Douala')::date as receipt_day,sum(amount_xaf) as amount from public.zp_cash_receipts where org_id=m.org_id and site_id=p_site and created_at>=((today-28)::timestamp at time zone 'Africa/Douala') and created_at<(today::timestamp at time zone 'Africa/Douala') group by 1)x;
 select coalesce(jsonb_agg(to_jsonb(x) order by x.post),'[]'::jsonb) into post_metrics from (select l.post,sum(l.qty) portions,sum(l.line_total_xaf) recorded_xaf from public.zp_cash_receipts r join public.zp_order_lines l on l.order_id=r.order_id where r.org_id=m.org_id and r.site_id=p_site and r.created_at>=lo and r.created_at<hi group by l.post)x;
 return jsonb_build_object('start',p_start,'end',p_end,'as_of',now(),'today',today,'first_recorded_sale_day',first_day,'recorded_xaf',revenue,'collected_xaf',(select coalesce(sum(amount_xaf),0) from public.zp_cash_receipts where org_id=m.org_id and site_id=p_site and method<>'credit' and created_at>=lo and created_at<hi)+(select coalesce(sum(amount_xaf),0) from public.zp_credit_payments where org_id=m.org_id and site_id=p_site and created_at>=lo and created_at<hi),'receipts',receipt_count,'uncosted_receipts',unknown_count,'known_cost_xaf',cost,'gross_margin_xaf',case when cost is not null then revenue-cost else null end,'expenses_xaf',expense,'current_low_stock',low_count,'current_late_orders',late_count,'feedback_count',feedback_count,'feedback_average',feedback_avg,'absolute_cash_variance_xaf',variance,'history_28',history,'posts',post_metrics);
end $$;
create or replace view public.zp_ledger_sources with (security_invoker=true) as
 select org_id,site_id,(case when method='credit' then 'credit_sale' else 'sale' end)::text as kind,id as source_id,(created_at at time zone 'Africa/Douala')::date as entry_date,amount_xaf,'Sale receipt'::text as label from public.zp_cash_receipts
 union all select r.org_id,r.site_id,'sale_cost',r.id,(r.created_at at time zone 'Africa/Douala')::date,sum(c.cost_xaf)::bigint,'Cost of sale' from public.zp_cash_receipts r join public.zp_sale_costs c on c.receipt_id=r.id group by r.id,r.org_id,r.site_id,r.created_at having count(*)=count(c.cost_xaf) and sum(c.cost_xaf)>0
 union all select org_id,site_id,'purchase_receipt',id,(created_at at time zone 'Africa/Douala')::date,cost_xaf,'Purchase receipt' from public.zp_purchase_receipts where cost_xaf>0
 union all select org_id,site_id,'supplier_payment',id,(created_at at time zone 'Africa/Douala')::date,amount_xaf,'Supplier payment' from public.zp_supplier_payments
 union all select org_id,site_id,'expense',id,expense_date,amount_xaf,label from public.zp_expenses
 union all select org_id,site_id,'inventory_loss',id,(created_at at time zone 'Africa/Douala')::date,loss_cost,reason from public.zp_inventory_counts where loss_cost>0
 union all select org_id,site_id,'deposit_'||direction,id,(created_at at time zone 'Africa/Douala')::date,amount_xaf,'Packaging deposit/refund' from public.zp_container_finance
 union all select org_id,site_id,'credit_payment',id,(created_at at time zone 'Africa/Douala')::date,amount_xaf,'Customer credit payment' from public.zp_credit_payments;
do $$ declare t text;f record;begin
 foreach t in array array['zp_credit_accounts','zp_credit_sales','zp_credit_payments'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select,insert,update,delete on public.%I to service_role',t);end loop;
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('zp_credit_status','zp_credit_account_add','zp_credit_authorize','zp_credit_collect','zp_credit_snapshot') loop execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;end $$;
commit;
